namespace ZoneEngine.Core.Packets
{
    using System;
    using System.Globalization;

    /// <summary>
    /// Exact accepted Sparrow/Phasefront capture bytes formerly embedded in AdventurerMorphFlightRuntime.
    /// Pure shared data only: no client, persistence, world or Legacy runtime dependency. Returned arrays
    /// are copies. Conditional SpellList blocks are intentionally not re-encoded by the Keeper serializer.
    /// Sparrow: 20260723-053632; Phasefront: 20260806-081845 and 20260806-085523.
    /// </summary>
    internal static class MorphCaptureWireCatalog
    {
        public const int SparrowCapturedCharacterInstance = 0x00139459;
        public const int PhasefrontCapturedCharacterInstance = 0x762ABC21;

        private static readonly byte[] SparrowApplyWire = Hex(
            "");

        private static readonly byte[] SparrowRemoveWire = Hex(
            "");

        private static readonly byte[] PhasefrontCamoApplyWire = Hex(
            "");

        private static readonly byte[] PhasefrontCamoRemoveWire = Hex(
            "");

        private static readonly byte[] PhasefrontExecutiveApplyWire = Hex(
            "");

        private static readonly byte[] PhasefrontExecutiveRemoveWire = Hex(
            "");

        private static readonly byte[] CanFlyEffectBlock = Hex(
            "0000CF9200014393000000040000000300000213000000000000000000000000000000000000007000000000000000000000000400000001000000000000000100000009");

        public static byte[] GetWire(int nanoId, bool remove)
        {
            byte[] template;
            if (nanoId == 82835) template = remove ? SparrowRemoveWire : SparrowApplyWire;
            else if (nanoId == 270542) template = remove ? PhasefrontCamoRemoveWire : PhasefrontCamoApplyWire;
            else if (nanoId == 288546) template = remove ? PhasefrontExecutiveRemoveWire : PhasefrontExecutiveApplyWire;
            else throw new ArgumentOutOfRangeException(nameof(nanoId), "No captured SpellList for this nano; hoverboard has none.");
            return (byte[])template.Clone();
        }

        public static byte[] GetCanFlyEffectBlock() => (byte[])CanFlyEffectBlock.Clone();

        private static byte[] Hex(string hex)
        {
            byte[] bytes = new byte[hex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
                bytes[i] = byte.Parse(hex.Substring(i * 2, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture);
            return bytes;
        }
    }
}
